(7667905, 1251086, 30861, '<td valign="top">And that''s my car, too! Though mine is red...</td>', 'And that''s my car, too! Though mine is red...', '2020-06-24 18:28:33.000000', NULL, 1),
(7667956, 1251067, 4008, '<td valign="top">Not an attractive image to me due to the high pixelation. Also I think it does not bring out anything special about a car, due to the composition etc.</td>', 'Not an attractive image to me due to the high pixelation. Also I think it does not bring out anything special about a car, due to the composition etc.', '2020-06-25 12:28:37.000000', NULL, 1),
(7667957, 1250853, 4008, '<td valign="top">Too much processing for my liking.</td>', 'Too much processing for my liking.', '2020-06-25 12:29:06.000000', NULL, 1),
(7667958, 1250982, 4008, '<td valign="top">Of all the car wreck images in this challenge, this one has a special atmosphere to me, in fact for me this is my favorite of all images in the challenge. Flower power (even though that was before my time)</td>', 'Of all the car wreck images in this challenge, this one has a special atmosphere to me, in fact for me this is my favorite of all images in the challenge. Flower power (even though that was before my time)', '2020-06-25 12:31:23.000000', NULL, 1),
(7667960, 1250728, 4008, '<td valign="top">lovely layered image, a lot to see, great atmosphere. Top 3 for me.</td>', 'lovely layered image, a lot to see, great atmosphere. Top 3 for me.', '2020-06-25 12:34:05.000000', NULL, 1),
(7667961, 1251215, 4008, '<td valign="top">Another great wreck in a beautiful landscape, but to me not as strong as the other, due to composition.</td>', 'Another great wreck in a beautiful landscape, but to me not as strong as the other, due to composition.', '2020-06-25 12:35:28.000000', NULL, 1),
(7667962, 1251032, 4008, '<td valign="top">I like the different approach, while still showing a recognisable car.</td>', 'I like the different approach, while still showing a recognisable car.', '2020-06-25 12:36:30.000000', NULL, 1),
(7667963, 1250872, 4008, '<td valign="top">Great angle, makes it look like a cartoon character.</td>', 'Great angle, makes it look like a cartoon character.', '2020-06-25 12:37:04.000000', NULL, 1),
(7667964, 1250815, 4008, '<td valign="top">Great atmosphere and dynamic approach. Would be even better if the source of the smoke was less obvious, just outside view.</td>', 'Great atmosphere and dynamic approach. Would be even better if the source of the smoke was less obvious, just outside view.', '2020-06-25 12:37:58.000000', NULL, 1),
(7667965, 1250743, 4008, '<td valign="top">The processing really adds to the winter feel. Volvo''s are built for this :-)</td>', 'The processing really adds to the winter feel. Volvo''s are built for this :-)', '2020-06-25 12:38:57.000000', NULL, 1),
(7667966, 1250753, 4008, '<td valign="top">Simple image but the colors makes this image really work well. Car was positioned at exactly the right spot, with the sun enhancing the colors.</td>', 'Simple image but the colors makes this image really work well. Car was positioned at exactly the right spot, with the sun enhancing the colors.', '2020-06-25 12:40:04.000000', NULL, 1),
(7667967, 1251222, 4008, '<td valign="top">Simple but intriguing image with the car fading into the darkness. It adds something special.</td>', 'Simple but intriguing image with the car fading into the darkness. It adds something special.', '2020-06-25 12:41:08.000000', NULL, 1),
(7667968, 1251250, 4008, '<td valign="top">Contrast between smooth car and rugged landscape, plus B&amp;W, works well.</td>', 'Contrast between smooth car and rugged landscape, plus B&W, works well.', '2020-06-25 12:42:05.000000', NULL, 1),
(7667969, 1250858, 4008, '<td valign="top">Funny, and the low perspective works well.</td>', 'Funny, and the low perspective works well.', '2020-06-25 12:42:42.000000', NULL, 1),
