(7668319, 1251236, 4008, '<td valign="top">The color of the rust contrasting with the beautiful landscape makes this image for me. Good composition as well with the truck positioned in the "calm" corner. Great. Top 3 for me.</td>', 'The color of the rust contrasting with the beautiful landscape makes this image for me. Good composition as well with the truck positioned in the "calm" corner. Great. Top 3 for me.', '2020-06-30 15:12:09.000000', NULL, 1),
(7668325, 1251155, 83313, '<td valign="top">I like the shot overall, cool old car and an appropriate treatment. However, there is some weirdness going on with some of the sharp contrasting edges of the car. Top of the hood, side windows, wheel well hump, various trim edges.</td>', 'I like the shot overall, cool old car and an appropriate treatment. However, there is some weirdness going on with some of the sharp contrasting edges of the car. Top of the hood, side windows, wheel well hump, various trim edges.', '2020-06-30 17:35:01.000000', NULL, 1),
(7668326, 1251228, 83313, '<td valign="top">Nice, though for me this treatment might have worked better with something a bit more retro. Personal preference is all that is. I do like the wideangle perspective. That work nicely for this.</td>', 'Nice, though for me this treatment might have worked better with something a bit more retro. Personal preference is all that is. I do like the wideangle perspective. That work nicely for this.', '2020-06-30 17:36:38.000000', NULL, 1),
(7668327, 1251098, 83313, '<td valign="top">Cropped a bit tight. Looks like this was at a car show, which are always a challenge due to crowds. I was at SEMA last year and despite having tons of photos of cool cars, between crowds and midday sun, I didn''t find any of the shots to be challenge material.</td>', 'Cropped a bit tight. Looks like this was at a car show, which are always a challenge due to crowds. I was at SEMA last year and despite having tons of photos of cool cars, between crowds and midday sun, I didn''t find any of the shots to be challenge material.', '2020-06-30 17:39:36.000000', NULL, 1),
(7668328, 1250952, 83313, '<td valign="top">Both weird and awesome. I need to rest my eyes, however.</td>', 'Both weird and awesome. I need to rest my eyes, however.', '2020-06-30 17:43:31.000000', NULL, 1),
